use std::fs
use std::collections::HashMap

fn amt(s: string) -> int {
    s.parse::<int>().unwrap_or(0)
}

fn main() {
    let text = fs::read_to_string("/dev/stdin").unwrap_or("")
    let mut acc: HashMap<string, int> = HashMap::new()
    for line in text.lines() {
        let p: Vec<string> = line.split_whitespace().map(|x| x.to_string()).collect()
        if p.len() == 0 { continue }
        let cmd = p[0].clone()
        if cmd == "open" && p.len() >= 3 {
            let a = amt(p[2].clone())
            let name = p[1].clone()
            if a < 0 {
                println("error: invalid amount")
            } else if acc.contains_key(name.clone()) {
                println("error: duplicate account")
            } else {
                acc.insert(name, a)
                println("ok")
            }
        } else if (cmd == "deposit" || cmd == "withdraw") && p.len() >= 3 {
            let a = amt(p[2].clone())
            let name = p[1].clone()
            if a <= 0 {
                println("error: invalid amount")
            } else if !acc.contains_key(name.clone()) {
                println("error: unknown account ${name}")
            } else {
                let bal: int = acc.get(name.clone()).unwrap_or(0)
                if cmd == "deposit" {
                    acc.insert(name, bal + a)
                    println("ok")
                } else if bal < a {
                    println("error: insufficient funds")
                } else {
                    acc.insert(name, bal - a)
                    println("ok")
                }
            }
        } else if cmd == "transfer" && p.len() >= 4 {
            let a = amt(p[3].clone())
            let f = p[1].clone()
            let t = p[2].clone()
            if a <= 0 {
                println("error: invalid amount")
            } else if !acc.contains_key(f.clone()) {
                println("error: unknown account ${f}")
            } else if !acc.contains_key(t.clone()) {
                println("error: unknown account ${t}")
            } else if f == t {
                println("error: same account")
            } else {
                let fb: int = acc.get(f.clone()).unwrap_or(0)
                let tb: int = acc.get(t.clone()).unwrap_or(0)
                if fb < a {
                    println("error: insufficient funds")
                } else {
                    acc.insert(f, fb - a)
                    acc.insert(t, tb + a)
                    println("ok")
                }
            }
        } else if cmd == "balance" && p.len() >= 2 {
            let name = p[1].clone()
            if !acc.contains_key(name.clone()) {
                println("error: unknown account ${name}")
            } else {
                println("${acc.get(name.clone()).unwrap_or(0)}")
            }
        }
    }
    let mut keys: Vec<string> = []
    for k in acc.keys() { keys.push(k.clone()) }
    keys.sort()
    for k in keys {
        println("${k} ${acc.get(k.clone()).unwrap_or(0)}")
    }
}

